package main

import "fmt"

type Order struct{ ID int }

// Concrete adapter, an outer-layer detail.
type PostgresRepo struct{}

func (PostgresRepo) Save(o Order) error { return nil }

// Port: declared at the CONSUMER, listing only the method it uses.
type repository interface {
	Save(o Order) error
}

type Service struct {
	repo repository // depend on the abstraction, not *PostgresRepo
}

func NewService(r repository) *Service { return &Service{repo: r} } // accept interface

func (s *Service) PlaceOrder(id int) error {
	return s.repo.Save(Order{ID: id})
}

// A fake adapter for tests — proves the seam works with any implementation.
type fakeRepo struct{ saved int }

func (f *fakeRepo) Save(o Order) error { f.saved++; return nil }

func main() {
	s := NewService(&fakeRepo{}) // inject the fake; no real database needed
	fmt.Println(s.PlaceOrder(1))
}

