package solution

import "errors"

// Balances is the port the Service needs, defined where it is consumed.
type Balances interface {
	Add(id string, amount int) error
	Get(id string) int
}

type Service struct {
	store Balances // depend on the abstraction, not a concrete store
}

func NewService(b Balances) *Service {
	return &Service{store: b} // accept the interface, return a struct
}

// Deposit enforces the business rule, then delegates persistence to the port.
func (s *Service) Deposit(id string, amount int) error {
	if amount <= 0 {
		return errors.New("deposit must be positive") // domain rule
	}
	return s.store.Add(id, amount)
}

func (s *Service) Balance(id string) int {
	return s.store.Get(id)
}

